  /**
   * What the slider adjusts. A range input renders no text, so without this
   * it announces as "slider, 60" with no indication of 60 of what.
   */
  label?: string;
  className?: string;
}) {
  const [internal, setInternal] = useState(value ?? 60);
  const v = value ?? internal;
  const pct = ((v - min) / (max - min)) * 100;
  return (
    <div className={cx("flex w-full items-center gap-4", className)}>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={v}
        onChange={(e) => {
          const n = Number(e.target.value);
          setInternal(n);
          onChange?.(n);
        }}
        aria-label={label}
        className="uicean-range w-full"
        style={{
          background: `linear-gradient(to right, #059669 0%, #059669 ${pct}%, var(--line) ${pct}%, var(--line) 100%)`,
        }}
      />
      <span className="w-14 shrink-0 text-right font-mono text-[13px] font-semibold text-ink tabular-nums">
        {v}
        {suffix}
      </span>
    </div>
  );
}

