}) {
  const [open, setOpen] = useState(false);
  const loc = locale ?? (typeof navigator !== "undefined" ? navigator.language : "en-GB");
  const fmt = new Intl.DateTimeFormat(loc, { dateStyle: "medium" });

  return (
    <Popover
      open={open}
      onOpenChange={setOpen}
