      <Calendar
        value={value}
        min={min}
        max={max}
        locale={loc}
        weekStartsOn={weekStartsOn}
        onChange={(d) => {
          onChange?.(d);
          setOpen(false);
        }}
      />
    </Popover>
  );
}

