/* Ring progress — 156/324 radial ref */
export function RingProgress({
  value,
  size = 20,
  stroke = 3,
  tone = "#10b981",
  className,
}: {
  value: number; // 0-1
  size?: number;
  stroke?: number;
  tone?: string;
  className?: string;
}) {
  const r = (size - stroke) / 2;
