/* ------------------------------------------------------------------ */
/* MODAL — portal dialog with backdrop                                 */
/* ------------------------------------------------------------------ */

export function Modal({
  open,
  onClose,
  children,
  width = "max-w-lg",
  label,
}: {
  open: boolean;
  onClose: () => void;
  children: ReactNode;
  width?: string;
  label?: string;
}) {
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", onKey);
    document.body.style.overflow = "hidden";
    panelRef.current?.querySelector<HTMLElement>("button, [href], input")?.focus();
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = "";
    };
  }, [open, onClose]);

  if (!open) return null;

  return createPortal(
    <div
      className="fixed inset-0 z-[90] flex items-center justify-center p-4"
      role="dialog"
      aria-modal="true"
      aria-label={label}
    >
      <div
        className="absolute inset-0 bg-[#1c1b18]/45 backdrop-blur-[3px] dark:bg-black/60"
        style={{ animation: "uicean-overlay-in 0.2s ease-out" }}
        onClick={onClose}
      />
      <div
        ref={panelRef}
        className={cx("relative w-full", width)}
        style={{ animation: "uicean-modal-in 0.22s cubic-bezier(0.2,0.9,0.3,1)" }}
      >
        {children}
      </div>
    </div>,
    document.body,
  );
}

