/* ------------------------------------------------------------------ */
/* useInView — shared intersection helper                              */
/* ------------------------------------------------------------------ */

function useInView<T extends HTMLElement>(threshold = 0.3) {
  const ref = useRef<T>(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([e]) => e.isIntersecting && setInView(true),
      { threshold },
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [threshold]);
  return { ref, inView };
}

/* ------------------------------------------------------------------ */
/* NUMBER TICKER — counts up when scrolled into view                   */
/* ------------------------------------------------------------------ */

export function NumberTicker({
  value,
  duration = 1400,
  prefix = "",
  suffix = "",
  decimals = 0,
  className,
}: {
  value: number;
  duration?: number;
  prefix?: string;
  suffix?: string;
  decimals?: number;
  className?: string;
}) {
  const { ref, inView } = useInView<HTMLSpanElement>(0.6);
  const [n, setN] = useState(0);
  useEffect(() => {
    if (!inView) return;
    let raf = 0;
    const t0 = performance.now();
    const tick = (t: number) => {
      const p = Math.min(1, (t - t0) / duration);
      const eased = 1 - Math.pow(1 - p, 3);
      setN(value * eased);
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [inView, value, duration]);
  return (
    <span ref={ref} className={cx("tabular-nums", className)}>
      {prefix}
      {n.toLocaleString("en-US", {
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals,
      })}
      {suffix}
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* TYPEWRITER — loops through words                                    */
/* ------------------------------------------------------------------ */

/**
 * The OS "reduce motion" setting, live.
 *
 * The stylesheet can calm a CSS animation, but a component driven by a timer
 * or requestAnimationFrame never sees it — those have to ask.
 */
export function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    if (typeof window === "undefined") return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);
  return reduced;
}

export function Typewriter({
  words,
  typeMs = 65,
  holdMs = 1400,
  className,
}: {
  words: string[];
  typeMs?: number;
  holdMs?: number;
  className?: string;
}) {
  const [wi, setWi] = useState(0);
  const [len, setLen] = useState(0);
  const [deleting, setDeleting] = useState(false);
  const word = words[wi % words.length];
  const reduced = useReducedMotion();

  useEffect(() => {
    /* the whole point of the component is a moving caret; under the setting
       it becomes the first word, spelled out and still */
    if (reduced) return;
    let t: number;
    if (!deleting && len < word.length) {
      t = window.setTimeout(() => setLen(len + 1), typeMs);
    } else if (!deleting && len === word.length) {
      t = window.setTimeout(() => setDeleting(true), holdMs);
    } else if (deleting && len > 0) {
      t = window.setTimeout(() => setLen(len - 1), typeMs / 2);
    } else {
      t = window.setTimeout(() => {
        setDeleting(false);
        setWi((w) => w + 1);
      }, 250);
    }
    return () => clearTimeout(t);
  }, [len, deleting, word, typeMs, holdMs, reduced]);

  /* Calming the motion must not delete the content: with the timer stopped
     `len` never advances, so the word is written out in full and the caret —
     which is only ever decoration — goes away with it. */
  if (reduced) {
    return <span className={className}>{words[0]}</span>;
  }

  return (
    <span className={className}>
      {word.slice(0, len)}
      <span
        aria-hidden
        className="ml-0.5 inline-block h-[1em] w-[2.5px] translate-y-[0.12em] rounded-full bg-current"
        style={{ animation: "uicean-caret 1.1s steps(1) infinite" }}
      />
    </span>
  );
}

